import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class SearchAutocomplete {
    private final TrieNode root = new TrieNode();

    private static class TrieNode {
        private final ConcurrentHashMap<Character, TrieNode> children = new ConcurrentHashMap<>();
        private boolean isEndOfterm;
        private final PriorityQueue<String> topCompletions = new PriorityQueue<>(
            (a, b) -> Integer.compare(frequency(b), frequency(a))
        );

        private int frequency(String term) { return 1; }
    }

    public void insert(String term) {
        TrieNode current = root;
        for (char c : term.toCharArray()) {
            current = current.children.computeIfAbsent(c, k -> new TrieNode());
            synchronized (current.topCompletions) {
                if (!current.topCompletions.contains(term)) {
                    current.topCompletions.offer(term);
                    if (current.topCompletions.size() > 5) {
                        current.topCompletions.poll();
                    }
                }
            }
        }
        current.isEndOfterm = true;
    }

    public List<String> autocomplete(String prefix) {
        TrieNode current = root;
        for (char c : prefix.toCharArray()) {
            current = current.children.get(c);
            if (current == null) return Collections.emptyList();
        }
        synchronized (current.topCompletions) {
            return new ArrayList<>(current.topCompletions);
        }
    }
}
